("2079","1","2021-09-04 12:24:43","2021-09-04 03:24:43","<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\"><strong>funk ojisanのオリジナルグッズ一覧です。</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2>①【2022年冬新作】パーカー発売</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>funk ojisanロゴパーカーができました！</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>色はネイビーとアッシュの2種類。<br>裏パイルになるので、春や秋にも着やすいです。</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":4147,\"width\":620,\"height\":465,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large is-resized\"><img src=\"http://psynogroup.boo.jp/koiwafunk/wp-content/uploads/2022/12/IMG_7288-1024x768.jpg\" alt=\"\" class=\"wp-image-4147\" width=\"620\" height=\"465\"/><figcaption class=\"wp-element-caption\"><meta charset=\"utf-8\">左：アッシュ（サイズL）　右：ネイビー（サイズL）</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":4146,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://psynogroup.boo.jp/koiwafunk/wp-content/uploads/2022/12/IMG_7285-1024x768.jpg\" alt=\"\" class=\"wp-image-4146\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:gallery {\"linkTo\":\"none\"} -->\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped\"><!-- wp:image {\"id\":4149,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://psynogroup.boo.jp/koiwafunk/wp-content/uploads/2022/12/IMG_7298-768x1024.jpg\" alt=\"\" class=\"wp-image-4149\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":4148,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://psynogroup.boo.jp/koiwafunk/wp-content/uploads/2022/12/IMG_7296-768x1024.jpg\" alt=\"\" class=\"wp-image-4148\"/></figure>\n<!-- /wp:image --></figure>\n<!-- /wp:gallery -->\n\n<!-- wp:image {\"id\":4186,\"width\":282,\"height\":167,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full is-resized\"><img src=\"http://psynogroup.boo.jp/koiwafunk/wp-content/uploads/2022/12/1dcc2441f23354ae2308b5aa06d52de4-1.png\" alt=\"\" class=\"wp-image-4186\" width=\"282\" height=\"167\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\"><strong>〈価格〉税込み¥8,380（送料別）</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"left\"} -->\n<p class=\"has-text-align-left\"><strong>〈サイズ〉S　/　M　/　L　/　XL　/　XXL</strong><br><strong>（XXLのみ税込み¥8,630になります）</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2>②【2022年夏Tシャツ】おじさんTシャツ</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><em><strong>funk ojisanのオリジナルTシャツ第2弾が登場！デザイン</strong></em><strong>は2種類、色がそれぞれ3種類ずつ用意してあります。</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":3050,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://psynogroup.boo.jp/koiwafunk/wp-content/uploads/2022/05/d9b2df6c2f1ab36a9dd5874b8283fe1c-1024x1024.jpg\" alt=\"\" class=\"wp-image-3050\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\"><strong>funk ojisan おじさんTシャツ<meta charset=\"utf-8\">〈価格〉税込み￥4,000（送料別）</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>①ライトブルー(S/XL)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>②ライムグリーン(S/XL)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>③イエロー(M/L/XL)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":3053,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://psynogroup.boo.jp/koiwafunk/wp-content/uploads/2022/05/7d580ebd75c22acab58fb2c0174e71b1-1-1024x1024.jpg\" alt=\"\" class=\"wp-image-3053\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\"><strong>GOLDEN VALVE Tシャツ<meta charset=\"utf-8\">〈価格〉税込み￥4,000（送料別）</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>①ブラック(M/L)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>②ホワイト(S/M/XL)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>③ゴールド<meta charset=\"utf-8\">(S/M/XL)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2>③【ラストチャンス！？】funk ojisan ロゴTシャツ</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":5} -->\n<h5 class=\"has-text-align-center\"><em><strong>funk ojisanのオリジナルTシャツが遂に再販！デザインは以下の2種類から！</strong></em></h5>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":5} -->\n<h5 class=\"has-text-align-center\">これがラストチャンス！？</h5>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":5} -->\n<h5 class=\"has-text-align-center\">※在庫に限りがあります</h5>\n<!-- /wp:heading -->\n\n<!-- wp:embed {\"url\":\"https://www.youtube.com/watch?v=T6lK4IEfIWY\",\"type\":\"video\",\"providerNameSlug\":\"youtube\",\"responsive\":true,\"className\":\"wp-embed-aspect-16-9 wp-has-aspect-ratio\"} -->\n<figure class=\"wp-block-embed is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\nhttps://www.youtube.com/watch?v=T6lK4IEfIWY\n</div></figure>\n<!-- /wp:embed -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\"><em>アキマツネオさんに書いて頂いたお馴染み『funk』ロゴと、ケンケン店長が書いた『ojisan』という師弟がコラボしたデザインとなっております。</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:gallery {\"linkTo\":\"none\"} -->\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped\"><!-- wp:image {\"id\":1938,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://psynogroup.boo.jp/koiwafunk/wp-content/uploads/2021/07/S__195682316-768x1024.jpg\" alt=\"\" class=\"wp-image-1938\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":1931,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://psynogroup.boo.jp/koiwafunk/wp-content/uploads/2021/07/S__22020119-1024x1024.jpg\" alt=\"\" class=\"wp-image-1931\"/></figure>\n<!-- /wp:image --></figure>\n<!-- /wp:gallery -->\n\n<!-- wp:image {\"id\":3052,\"width\":293,\"height\":206,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full is-resized\"><img src=\"http://psynogroup.boo.jp/koiwafunk/wp-content/uploads/2022/05/S__22036504-300x300-3.jpg\" alt=\"\" class=\"wp-image-3052\" width=\"293\" height=\"206\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\"><strong><meta charset=\"utf-8\">〈価格〉S〜L：税込み価格3,850円、XL：3,905円、XXL：4,125円（送料別）</strong><br>②ネイビーTシャツに白文字（S）<br>③白Tシャツに黒文字（XXL）</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2><strong>【ご注文方法</strong>】</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>専用のメールアドレスでのご注文となります。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>ーーー</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>【名前(フルネーム)】</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>【住所（郵便番号から）】</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>【電話番号】</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>【ご希望のシャツの種類、サイズと番号】</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>ーーー</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"fontSize\":\"large\"} -->\n<p class=\"has-text-align-center has-large-font-size\"><br>上記のテンプレをコピーして<br><a href=\"mailto:funkojisan.goods@gmail.com\">funkojisan.goods@gmail.com</a><br>にメールを送信してください。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#a30012\"}}} -->\n<p class=\"has-text-color\" style=\"color:#a30012\">※パーカーをご注文のお客様は製作にお時間を頂くため、商品発送は1月頃を予定しております、ご了承くださいませ。</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>送料：全国一律￥1,000</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>※Tシャツ1枚のみご購入の場合のみ（全国送料￥300）</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:gallery {\"linkTo\":\"none\"} -->\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped\"></figure>\n<!-- /wp:gallery -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2></h2>\n<!-- /wp:heading -->","【funk ojisanオリジナルグッズ】","","publish","closed","closed","","newtshirts","","","2023-02-25 15:37:16","2023-02-25 06:37:16","","0","http://psynogroup.boo.jp/koiwafunk/?page_id=2079","0","page","","0"),
