("3064","1","2022-05-11 17:56:57","2022-05-11 08:56:57","<!-- wp:paragraph -->\n<p>掲示板</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link\">売りたい掲示板</a></div>\n<!-- /wp:button -->\n\n<!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link\">書いたい掲示板</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->","売りたい書いたい","","inherit","closed","closed","","3061-revision-v1","","","2022-05-11 17:56:57","2022-05-11 08:56:57","","3061","http://psynogroup.boo.jp/koiwafunk/?p=3064","0","revision","","0"),
